<script lang="ts">
  import GameIcon from "./GameIcon.svelte";
  import {localGameArtwork} from './local_game_art';
  import { onMount } from "svelte";
  import { invoke } from "@tauri-apps/api/core";
  import { openUrl } from "@tauri-apps/plugin-opener";
  import SkinModelViewer from "./SkinModelViewer.svelte";
  import UiIcon from "./UiIcon.svelte";
  import { HELD_ITEMS, itemsForPose, type HeldItemId, type EquippedItems } from "./held_items";
  import { POSES, POSE_CATEGORIES, JOINTS, JOINT_LABELS, FALLBACK_SKIN, clonePose, type Pose, type Joint } from "./poses_catalog";
  let {skinUrl=FALLBACK_SKIN,fallbackSkinUrl="",capeUrl,model="auto-detect",onclose}: {skinUrl?:string;fallbackSkinUrl?:string;capeUrl?:string;model?:"default"|"slim"|"auto-detect";onclose?:()=>void}=$props();
  let viewer: ReturnType<typeof SkinModelViewer> | undefined;
  let pose=$state<Pose>(clonePose(POSES[0]));let custom=$state<Pose[]>([]);let selected=$state(POSES[0].id);
  let category=$state("all");let search=$state("");let joint=$state<Joint>("head");let name=$state("");
  let lightIntensity=$state(1.8);let lightRotation=$state(-35);let fov=$state(42);let outerLayer=$state(true);let breathing=$state(true);
  let message=$state("");let busy=$state(false);let resolution=$state(2048);
  let rightItem=$state<HeldItemId>('none');let leftItem=$state<HeldItemId>('none');let automaticEquipment=$state(true);
  let savedEquipment:Record<string,EquippedItems>={};
  let catalog=$derived([...POSES,...custom]);
  let filtered=$derived(catalog.filter(p=>(category==="all"||p.category===category)&&p.name.toLocaleLowerCase().includes(search.toLocaleLowerCase())));
  onMount(()=>{try{const value=JSON.parse(localStorage.getItem('launchertps.poseEquipment.v1')??'{}');if(value&&typeof value==='object'&&!Array.isArray(value))savedEquipment=value;}catch{ }void invoke<Pose[]>("list_custom_poses").then(items=>custom=items).catch(error=>message=String(error));});
  function choose(id:string){const source=catalog.find(p=>p.id===id);if(!source)return;selected=id;pose=clonePose(source);name=source.category==="Personalizadas"?source.name:"";const stored=savedEquipment[id];if(stored&&HELD_ITEMS.some(item=>item.id===stored.right)&&HELD_ITEMS.some(item=>item.id===stored.left)){rightItem=stored.right;leftItem=stored.left;}else if(automaticEquipment){const items=itemsForPose(source);rightItem=items.right;leftItem=items.left;}}
  function updateJoint(axis:number,value:string){const next=clonePose(pose);next.joints[joint][axis]=Number(value);pose=next;}
  function updateRoot(field:"position"|"rotation",axis:number,value:string){const next=clonePose(pose);next[field][axis]=Number(value);pose=next;}
  function reset(){choose(selected);lightIntensity=1.8;lightRotation=-35;fov=42;outerLayer=true;}
  async function save(){if(!name.trim()){message="Ponle un nombre a tu pose.";return;}busy=true;try{const item={...clonePose(pose),id:selected.startsWith("custom-")?selected:`custom-${crypto.randomUUID()}`,name:name.trim(),category:"Personalizadas"};const saved=await invoke<Pose>("save_custom_pose",{pose:item});custom=[...custom.filter(p=>p.id!==saved.id),saved];selected=saved.id;pose=clonePose(saved);savedEquipment[saved.id]={right:rightItem,left:leftItem};try{localStorage.setItem('launchertps.poseEquipment.v1',JSON.stringify(savedEquipment));}catch{ }message="Pose guardada en tu biblioteca del editor.";}catch(error){message=String(error);}finally{busy=false;}}
  async function remove(){if(!selected.startsWith("custom-"))return;try{await invoke("delete_custom_pose",{id:selected});custom=custom.filter(p=>p.id!==selected);choose(POSES[0].id);message="Pose eliminada.";}catch(error){message=String(error);}}
  function openCredit(event:MouseEvent,url:string){event.preventDefault();void openUrl(url).catch(error=>message=`No se pudo abrir el enlace: ${String(error)}`);}
  async function exportImage(clipboard=false){if(!viewer)return;busy=true;message="Renderizando PNG transparente…";try{const blob=await viewer.renderPng(resolution,resolution);if(clipboard){if(!navigator.clipboard?.write||typeof ClipboardItem==="undefined")throw new Error("El portapapeles de imágenes no está disponible. Usa Descargar PNG.");await navigator.clipboard.write([new ClipboardItem({"image/png":blob})]);message="Render copiado al portapapeles.";}else{const encoded=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});const path=await invoke<string>("save_pose_render",{imageBase64:encoded,name:pose.name});message=`Render PNG guardado: ${path}`;}}catch(error){message=String(error);}finally{busy=false;}}
</script>

<section class="poser-studio">
  <header class="studio-header"><div><span class="eyebrow">CREATIVIDAD EN CADA ARTICULACIÓN</span><h1><span>Estudio de Renderizado y Poses 3D</span></h1><p>Compón una escena, equipa a tu personaje y crea tu próxima miniatura.</p><small class="resource-source">{$localGameArtwork.source}</small></div><div class="header-actions"><a class="open-source" href="https://bs-community.github.io/skinview3d/" target="_blank" rel="noopener noreferrer" onclick={event=>openCredit(event,"https://bs-community.github.io/skinview3d/")}>Visor skinview3d · Web oficial <span aria-hidden="true">↗</span></a>{#if onclose}<button onclick={onclose}><UiIcon name="left" size={16}/>Volver a Jugar</button>{/if}</div></header>
  <div class="studio-grid">
    <aside class="catalog-panel panel"><div class="panel-title"><h2>Biblioteca de poses</h2><span>{catalog.length}</span></div><input placeholder="Buscar pose…" aria-label="Buscar pose en estudio" bind:value={search}/><select aria-label="Categoría" bind:value={category}><option value="all">Todas las categorías</option>{#each [...POSE_CATEGORIES,...(custom.length?["Personalizadas"]:[])] as item}<option value={item}>{item}</option>{/each}</select><div class="pose-list">{#each filtered as item}<button class:active={selected===item.id} onclick={()=>choose(item.id)}><GameIcon name="armor_stand" size={18}/><span>{item.name}</span><small>{item.category}</small></button>{/each}{#if !filtered.length}<p>No hay poses para esta búsqueda.</p>{/if}</div></aside>
    <section class="preview-panel panel"><div class="preview-title"><div><span class="eyebrow">VISTA PREVIA EN TIEMPO REAL</span><h2>{pose.name}</h2></div><label class="check"><input type="checkbox" bind:checked={breathing}/>Respiración</label></div><SkinModelViewer {fallbackSkinUrl} bind:this={viewer} {skinUrl} {capeUrl} {model} {pose} {breathing} {lightIntensity} {lightRotation} {fov} {outerLayer} {rightItem} {leftItem} height={490}/><div class="export-row"><select aria-label="Resolución del render" bind:value={resolution}><option value={1024}>1024 × 1024</option><option value={2048}>2048 × 2048 · HD</option><option value={4096}>4096 × 4096 · 4K</option></select><button class="primary" onclick={()=>exportImage()} disabled={busy}><UiIcon name="download" size={16}/>Descargar render PNG</button><button onclick={()=>exportImage(true)} disabled={busy}><UiIcon name="copy" size={16}/>Copiar imagen</button><button onclick={()=>invoke("open_pose_renders").catch(error=>message=String(error))}><UiIcon name="image" size={16}/>Ver renders</button></div><small class="export-note">PNG con transparencia real. Las texturas, los objetos equipados y los ajustes se conservan durante la captura.</small></section>
    <aside class="settings-panel panel"><h2>Articulaciones</h2><div class="joint-tabs">{#each JOINTS as item}<button class:active={joint===item} onclick={()=>joint=item}><UiIcon name="pose" size={14}/>{JOINT_LABELS[item]}</button>{/each}</div><div class="joint-controls"><h3>{JOINT_LABELS[joint]}</h3>{#each ["X","Y","Z"] as axis,index}<label><span>Rotación {axis}<output>{pose.joints[joint][index]}°</output></span><input aria-label="{JOINT_LABELS[joint]} rotación {axis}" type="range" min="-180" max="180" step="1" value={pose.joints[joint][index]} oninput={event=>updateJoint(index,event.currentTarget.value)}/></label>{/each}</div>
      <details open class="equipment-panel"><summary><UiIcon name="cube" size={15}/>Objetos en las manos</summary><label>Mano derecha<select bind:value={rightItem} onchange={()=>automaticEquipment=false}>{#each HELD_ITEMS as item}<option value={item.id} disabled={item.id!=='none'&&!$localGameArtwork.models[item.id]}>{item.name}{item.id!=='none'&&!$localGameArtwork.models[item.id]?' · No disponible en esta versión':''}</option>{/each}</select></label><label>Mano izquierda<select bind:value={leftItem} onchange={()=>automaticEquipment=false}>{#each HELD_ITEMS as item}<option value={item.id} disabled={item.id!=='none'&&!$localGameArtwork.models[item.id]}>{item.name}{item.id!=='none'&&!$localGameArtwork.models[item.id]?' · No disponible en esta versión':''}</option>{/each}</select></label><label class="check"><input type="checkbox" bind:checked={automaticEquipment} onchange={()=>{if(automaticEquipment){const items=itemsForPose(pose);rightItem=items.right;leftItem=items.left;}}}/>Equipar según la pose</label><small>Solo se equipan objetos con modelos y texturas locales de esta versión; siguen las manos y se incluyen en el PNG. Los recursos ausentes quedan ocultos.</small></details>
      <details><summary>Posición e inclinación del personaje</summary>{#each ["position","rotation"] as field}<h3>{field==="position"?"Posición":"Inclinación"}</h3>{#each ["X","Y","Z"] as axis,index}<label><span>{axis}<output>{pose[field as "position"|"rotation"][index]}{field==="rotation"?"°":""}</output></span><input aria-label="{field} {axis}" type="range" min={field==="position"?-15:-180} max={field==="position"?15:180} step={field==="position"?0.5:1} value={pose[field as "position"|"rotation"][index]} oninput={event=>updateRoot(field as "position"|"rotation",index,event.currentTarget.value)}/></label>{/each}{/each}</details>
      <details open><summary>Luz y cámara</summary><label><span>Intensidad de luz<output>{lightIntensity.toFixed(1)}</output></span><input aria-label="Intensidad de luz" type="range" min="0" max="5" step="0.1" bind:value={lightIntensity}/></label><label><span>Dirección de luz<output>{lightRotation}°</output></span><input aria-label="Rotación de luz" type="range" min="-180" max="180" bind:value={lightRotation}/></label><label><span>Campo de visión<output>{fov}°</output></span><input aria-label="Campo de visión" type="range" min="20" max="80" bind:value={fov}/></label><label class="check"><input type="checkbox" bind:checked={outerLayer}/>Segunda capa de ropa y sombrero</label></details>
      <div class="save-panel"><label for="custom-pose-name">Guardar tu pose</label><input id="custom-pose-name" placeholder="Nombre de tu pose" maxlength="80" bind:value={name}/><button class="primary" onclick={save} disabled={busy}><UiIcon name="save" size={16}/>Guardar pose personalizada</button><div class="save-actions"><button onclick={reset}><UiIcon name="refresh" size={15}/>Restablecer</button>{#if selected.startsWith("custom-")}<button class="danger" onclick={remove}><UiIcon name="trash" size={15}/>Eliminar</button>{/if}</div></div>
    </aside>
  </div>
  {#if message}<p class="studio-message" role="status">{message}</p>{/if}
  <footer class="project-credits" aria-label="Créditos del visor 3D">
    <div><strong>Gracias a la comunidad open source</strong><p>Visor 3D con <a href="https://bs-community.github.io/skinview3d/" target="_blank" rel="noopener noreferrer" onclick={event=>openCredit(event,"https://bs-community.github.io/skinview3d/")}>skinview3d</a>, de Kent Rasmussen, Haowei Wen, Sean Boult y colaboradores, sobre <a href="https://threejs.org/" target="_blank" rel="noopener noreferrer" onclick={event=>openCredit(event,"https://threejs.org/")}>Three.js</a>, de sus autores y colaboradores.</p></div>
    <nav aria-label="Proyectos originales"><a href="https://github.com/bs-community/skinview3d" target="_blank" rel="noopener noreferrer" onclick={event=>openCredit(event,"https://github.com/bs-community/skinview3d")}>Código de skinview3d <span aria-hidden="true">↗</span></a><a href="https://github.com/bs-community/skinview3d/blob/master/LICENSE" target="_blank" rel="noopener noreferrer" onclick={event=>openCredit(event,"https://github.com/bs-community/skinview3d/blob/master/LICENSE")}>Licencia MIT · skinview3d</a><a href="https://github.com/mrdoob/three.js/blob/dev/LICENSE" target="_blank" rel="noopener noreferrer" onclick={event=>openCredit(event,"https://github.com/mrdoob/three.js/blob/dev/LICENSE")}>Licencia MIT · Three.js</a></nav>
  </footer>
</section>

<style>
  .resource-source{display:block;color:var(--text-secondary);font-size:.7rem;margin-top:8px}.project-credits{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:22px;padding:17px 20px;border:1px solid #b99ae21b;border-radius:14px;background:#10111a91;color:#a798b5;font-size:.68rem;line-height:1.7}.project-credits strong{color:#c7bad5;font-size:.72rem;font-weight:600}.project-credits p{margin:5px 0 0;max-width:700px}.project-credits a{color:#ceb0e9;text-decoration:none;text-underline-offset:3px}.project-credits a:hover{text-decoration:underline;color:#f2dfff}.project-credits nav{display:flex;gap:5px 16px;flex-wrap:wrap;justify-content:flex-end;max-width:320px}.project-credits a:focus-visible,.open-source:focus-visible{outline:2px solid var(--primary,#c084fc);outline-offset:4px}.header-actions .open-source{text-decoration:none;transition:border-color .16s,color .16s}.header-actions .open-source:hover{border-color:#bc8cee90;color:#ecd9ff}@media(max-width:700px){.project-credits{display:block;padding:16px}.project-credits nav{margin-top:12px;max-width:none;justify-content:flex-start}.header-actions .open-source{display:inline-block}}
  .poser-studio{color:#e9e1f3;max-width:1800px;margin:auto}.studio-header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.eyebrow{font-size:.6rem;letter-spacing:.18em;color:#a68abf;font-weight:650}h1{margin:7px 0;font-size:2.3rem;letter-spacing:-.06em}h1 span{color:var(--primary,#bb86ef)}.studio-header p{color:#a496b6;font-size:.85rem;margin:0}.header-actions{display:flex;align-items:center;gap:15px;flex-wrap:wrap}.open-source{font-size:.65rem;color:#a995bf;border:1px solid #b98feb26;border-radius:20px;padding:7px 10px}.studio-grid{display:grid;grid-template-columns:225px minmax(280px,1fr) 280px;gap:16px;align-items:start}.panel{border:1px solid #b99ae22b;background:linear-gradient(140deg,#281d3ac7,#11121edb);border-radius:18px;min-width:0;padding:17px;box-sizing:border-box}h2{font-size:.9rem;margin:0 0 14px}h3{font-size:.76rem;margin:14px 0 10px;color:#d4b8ee}.panel-title{display:flex;align-items:center;justify-content:space-between}.panel-title span{font-size:.65rem;color:#bb91df}.catalog-panel>input,.catalog-panel>select{margin-bottom:9px}input:not([type=range]):not([type=checkbox]),select{width:100%;min-width:0;box-sizing:border-box;border:1px solid #c5a8e92d;border-radius:8px;background:#11101ecc;color:#ded3eb;padding:9px;font-size:.75rem;outline:none;color-scheme:dark}button{border:1px solid #b69ad82d;border-radius:8px;padding:9px 11px;background:#ad7ae810;color:#cfc0df;font-size:.72rem;cursor:pointer;transition:.16s}button:hover,button.active{border-color:#bc8cee90;background:#a56ce225;color:#ecd9ff}button:disabled{opacity:.45;cursor:wait}.primary{background:linear-gradient(100deg,#a162d64f,#7963d14f);border-color:#b682e969;color:#edddff}.pose-list{max-height:660px;overflow:auto;scrollbar-width:thin;scrollbar-color:#71518a44 transparent;display:grid;gap:5px}.pose-list button{text-align:left;padding:10px;display:flex;flex-direction:column;gap:5px}.pose-list small{font-size:.59rem;color:#9a87ad}.pose-list p{font-size:.75rem;color:#ac9bbb}.preview-panel{padding:0;overflow:hidden}.preview-title{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:19px 20px 0}.preview-title h2{margin:5px 0 0;font-size:1rem}.export-row{padding:15px 16px 6px;display:flex;gap:7px;flex-wrap:wrap}.export-row select{width:auto;flex:1}.export-note{display:block;font-size:.64rem;color:#9583a8;padding:6px 17px 17px}.joint-tabs{display:flex;gap:5px;flex-wrap:wrap}.joint-tabs button{font-size:.63rem;padding:7px 8px}.joint-controls{margin-top:12px}label:not(.check){display:block;margin:11px 0;font-size:.72rem;color:#bba6cf}label>span{display:flex;justify-content:space-between;gap:10px}output{color:#d7b2f3;font-size:.69rem;font-variant-numeric:tabular-nums}input[type=range]{width:100%;accent-color:#b57cea;height:4px;margin:12px 0 5px}input[type=checkbox]{accent-color:#b57cea}.check{display:flex;align-items:center;gap:5px;font-size:.66rem;color:#b29ac7}.preview-title .check{white-space:nowrap}details{border-top:1px solid #bca1db1a;margin-top:15px;padding-top:13px}summary{cursor:pointer;font-size:.73rem;color:#d0b1e6}.save-panel{border-top:1px solid #bca1db1a;margin-top:18px;padding-top:4px}.save-panel>button{width:100%;margin-top:9px}.save-actions{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}.save-actions button{flex:1;font-size:.63rem;padding:7px}.danger{color:#e8a7b7}.studio-message{font-size:.8rem;color:#d4b6ed;background:#a978e311;border:1px solid #be94ec25;border-radius:10px;padding:13px 17px;overflow-wrap:anywhere}input:focus,select:focus{border-color:#bc8dee}@media(max-width:1250px){.studio-grid{grid-template-columns:180px minmax(260px,1fr)}.settings-panel{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:10px 25px}.settings-panel>h2{grid-column:1/-1}.joint-tabs{grid-column:1/-1}.save-panel{margin-top:0}.pose-list{max-height:620px}}@media(max-width:700px){.studio-grid{grid-template-columns:1fr}.settings-panel{display:block}.catalog-panel{max-height:240px}.pose-list{max-height:100px;grid-template-columns:1fr 1fr}.catalog-panel>input,.catalog-panel>select{display:inline-block;width:48%}.studio-header{align-items:start}.open-source{display:none}}
  .equipment-panel summary{display:flex;align-items:center;gap:7px}.equipment-panel label select{margin-top:7px}.equipment-panel>small{display:block;color:#9788aa;font-size:.64rem;line-height:1.6;margin-top:10px}.studio-header h1{font-size:clamp(1.5rem,2.3vw,2.1rem);max-width:720px;line-height:1.12}.equipment-panel .check{line-height:1.5}
</style>
